let lang='he',page='dashboard',selected=0,healthSelected=0,invoiceSelected=0,invoiceVisible=false,healthVisible=false,feedback='',role='owner';const keys=['dashboard','members','profile','newMember','monthlyBills','invoices','health','reminders','client'];const t=k=>dict[lang][k]||k;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=d=>d?d.split('-').reverse().join('/'):'—';const pn=p=>lang==='he'?p.name:p.ru;const stat=(v)=>`<span class="badge ${v==='soon'||v==='pending'?'warn':v==='expired'||v==='missing'?'bad':''}">${t(v)}</span>`;const btn=(text,action,cls='alt')=>`<button class="btn ${cls}" onclick="${action}">${text}</button>`;const options=(idx)=>people.map((p,i)=>`<option value="${i}" ${i===idx?'selected':''}>${esc(pn(p))}</option>`).join('');const field=(label,name,type='text',value='',required=true)=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`;const note=()=>`<p class="muted small">${t('note')}</p>`;function go(p){page=p;invoiceVisible=false;healthVisible=false;render();window.scrollTo(0,0)}function choose(i){selected=+i;go('profile')}function healthFor(i){healthSelected=+i;go('health')}function renew(i){invoiceSelected=+i;invoiceVisible=false;page='invoices';render()}function invoiceFor(i){invoiceSelected=+i;invoiceVisible=false;go('invoices')}
function dashboard(){return receiptsAlert()+`<div class="dashboard-title"><h2>${lang==='he'?'תמונת מצב':'Обзор студии'}</h2><span class="muted small">${lang==='he'?'נתוני הדגמה':'Демо-данные'}</span></div><div class="cards"><div class="card"><span class="icon">♟</span><div class="muted">${t('activeCount')}</div><strong>3</strong><span class="small muted">/ 5</span></div><div class="card"><span class="icon">◷</span><div class="muted">${t('ending')}</div><strong>2</strong><span class="small muted">04–07/11/2026</span></div><div class="card"><span class="icon">✓</span><div class="muted">${t('invoicesSent')}</div><strong>3</strong><span class="small muted">11/2026</span></div><div class="card"><span class="icon">▤</span><div class="muted">${t('invoicesPending')}</div><strong>2</strong><span class="small muted">11/2026</span></div></div><div class="panel"><div class="dashboard-title"><h2>${t('upcoming')}</h2><button class="link" onclick="go('members')">${lang==='he'?'כל המתאמנים':'Все клиенты'}</button></div>${membersTable([1,2])}</div><div class="panel">${note()}</div>`}
/* Point 2: fixed fictitious November 2026 monthly bills, independent of receipt issuance. */
const demoMonthlyBills=[
 {member:0,month:'11/2026',amount:150,status:'paid'},
 {member:1,month:'11/2026',amount:150,status:'pending'},
 {member:2,month:'11/2026',amount:180,status:'pending'},
 {member:3,month:'11/2026',amount:150,status:'paid'},
 {member:4,month:'11/2026',amount:200,status:'paid'}
];
function monthlyBills(){
 const bills=demoMonthlyBills.filter(b=>people[b.member]);
 return `<div class="panel"><div class="dashboard-title"><h2>${t('monthlyBills')} · 11/2026</h2><span class="badge warn">${t('demo')}</span></div><p class="muted small">${t('monthlyBillDemo')}</p><div class="table monthly-bills-table"><table><thead><tr><th>${t('name')}</th><th>${t('billMonth')}</th><th>${t('billAmount')} (₪)</th><th>${t('status')}</th><th>${t('actions')}</th></tr></thead><tbody>${bills.map(b=>`<tr><td><button class="member-shortcut" onclick="choose(${b.member})">${esc(pn(people[b.member]))}</button></td><td data-label="${t('billMonth')}">${b.month}</td><td data-label="${t('billAmount')}">₪${b.amount.toFixed(2)}</td><td data-label="${t('status')}">${stat(b.status)}</td><td>${b.status==='pending'?btn(t('newSubscription'),`renew(${b.member})`):'—'}</td></tr>`).join('')}</tbody></table></div></div>`;
}
function membersTable(ids=people.map((_,i)=>i)){return `<div class="table member-table"><table><thead><tr><th>${t('name')}</th><th>${t('status')}</th><th>${t('end')}</th><th>${t('healthStatus')}</th><th>${t('actions')}</th></tr></thead><tbody>${ids.map(i=>`<tr><td><button class="member-shortcut" onclick="choose(${i})">${esc(pn(people[i]))}</button></td><td data-label="${t('status')}">${stat(people[i].status)}</td><td data-label="${t('end')}">${fmt(people[i].end)}</td><td data-label="${t('healthStatus')}"><span class="badge ${people[i].medical?'status-medical-ok':'status-medical-missing'}">${people[i].medical?t('received'):t('missing')}</span></td><td><button class="link" onclick="choose(${i})">${t('view')}</button></td></tr>`).join('')}</tbody></table></div>`}
function members(){return `<div class="panel"><div class="row between"><h2>${t('members')} · ${people.length}</h2>${btn(t('newMember'),"go('newMember')",'')}</div>${membersTable()}</div>`}
function profile(){const p=people[selected],m=p.measure.at(-1),bmi=(m[2]/((m[1]/100)**2)).toFixed(1);return `<div class="panel"><div class="row between"><h2>${esc(pn(p))} · ${stat(p.status)}</h2><select onchange="choose(this.value)">${options(selected)}</select></div><div class="grid2"><div><h3>${t('myDetails')}</h3><p><b>${t('username')}:</b> ${esc(p.username)}</p><p><b>${t('age')}:</b> ${p.age}</p><p><b>${t('phone')}:</b> <bdi>${p.phone}</bdi></p><p><b>${t('email')}:</b> <bdi>${p.email}</bdi></p><p><b>${t('end')}:</b> ${fmt(p.end)}</p><p><b>${t('healthStatus')}:</b> ${stat(p.medical?'received':'missing')}</p>${btn(t('openHealth'),`healthFor(${selected})`)}</div><div><h3>${t('measurements')}</h3><div class="metrics">${[[t('height'),m[1]],[t('weight'),m[2]],[t('fat'),m[3]+'%'],[t('muscle'),m[4]],[t('water'),m[5]+'%'],[t('bmi'),bmi]].map(a=>`<div class="metric"><span class="small muted">${a[0]}</span><b>${a[1]}</b></div>`).join('')}</div><p class="muted small">${t('measurementDate')}: ${fmt(m[0])}</p></div></div></div><div class="panel"><h2>${t('measureHistory')}</h2><div class="table responsive-table-target measurement-history-scroll" tabindex="0" role="region" aria-label="${t('measureHistory')}"><table><thead><tr><th>${t('date')}</th><th>${t('height')}</th><th>${t('weight')}</th><th>${t('fat')}</th><th>${t('muscle')}</th><th>${t('water')}</th></tr></thead><tbody>${p.measure.map(x=>`<tr>${[fmt(x[0]),...x.slice(1)].map(y=>`<td>${y}</td>`).join('')}</tr>`).join('')}</tbody></table></div><form onsubmit="addMeasurement(event)" class="grid3">${field(t('measurementDate'),'date','date','2026-11-02')}${field(t('height'),'height','number',m[1])}${field(t('weight'),'weight','number',m[2])}${field(t('fat'),'fat','number',m[3])}${field(t('muscle'),'muscle','number',m[4])}${field(t('water'),'water','number',m[5])}<button class="btn" type="submit">${t('addMeasure')}</button></form></div><div class="panel"><h2>${t('subHistory')}</h2><p>${fmt(p.start)} — ${fmt(p.end)} · ${t('monthly')}</p><p class="muted small">${t('demo')}</p></div>`}
function addMeasurement(e){e.preventDefault();const f=new FormData(e.target);people[selected].measure.push([f.get('date'),...['height','weight','fat','muscle','water'].map(k=>+f.get(k))]);feedback=t('savedMeasure');render()}
function createMember(e){e.preventDefault();go('newMember')}
/* Phase 1 : le reçu légal est émis dans Slate (logiciel enregistré auprès de רשות המסים).
   Le site n'émet ni ne numérote aucun document fiscal : il enregistre le paiement,
   le numéro et le lien du reçu Slate, puis l'envoi au client. */
let receipts=[];
const SLATE_APP='https://app.slate.co.il';
const newPayId=()=>'pay-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);
const todayISO=()=>new Date().toISOString().slice(0,10);
const waPhone=ph=>{let d=String(ph||'').replace(/\D/g,'');if(d.startsWith('00'))d=d.slice(2);if(d.startsWith('0'))d='972'+d.slice(1);return d.length>=11?d:''};
const receiptStatus=st=>{const m={toIssue:['bad',wz('להפקה ב-Slate','Оформить в Slate')],issued:['warn',wz('הופקה · לשליחה','Оформлена · отправить')],sent:['',wz('נשלחה','Отправлена')]}[st]||['bad',st];return `<span class="badge ${m[0]}">${m[1]}</span>`};
function receiptsAlert(){const n=receipts.filter(r=>r.status==='toIssue').length,m=receipts.filter(r=>r.status==='issued').length;if(!n&&!m)return '';return `<div class="receipt-alert" role="status"><b>${wz('קבלות פתוחות','Незакрытые квитанции')}:</b> ${n?wz(n+' תשלומים בלי קבלה','Платежей без квитанции: '+n):''}${n&&m?' · ':''}${m?wz(m+' קבלות שעוד לא נשלחו','Не отправлено: '+m):''} <button class="link" onclick="go('invoices')">${wz('לטיפול','Открыть')}</button></div>`}
const DEMO_KEY='leonid-v16-nonmedical-demo';
function saveDemo(){try{localStorage.setItem(DEMO_KEY,JSON.stringify({members:people.filter(p=>p.demoAdded).map(p=>({name:p.name,ru:p.ru,username:p.username,age:p.age,phone:p.phone,email:p.email,start:p.start,end:p.end,status:p.status,measure:p.measure,demoAdded:true})),receipts}))}catch(e){console.warn('Demo storage unavailable',e)}}
function loadDemo(){try{const d=JSON.parse(localStorage.getItem(DEMO_KEY)||'{}');if(Array.isArray(d.members))for(const m of d.members){if(m&&m.demoAdded&&typeof m.name==='string')people.push({...m,medical:false,medicalReview:'pending'})}if(Array.isArray(d.receipts))receipts=d.receipts.filter(x=>x&&typeof x.id==='string'&&['toIssue','issued','sent'].includes(x.status))}catch(e){console.warn('Demo storage corrupt',e)}}
loadDemo();

function recordPayment(e){e.preventDefault();const f=new FormData(e.target),amount=Number(f.get('amount'));if(!(amount>0))return;const person=Number(f.get('person'));if(!people[person])return;receipts.unshift({id:newPayId(),person,amount,method:String(f.get('method')||''),date:String(f.get('date')||todayISO()),description:String(f.get('description')||'מנוי חודשי'),status:'toIssue',slateNo:'',slateUrl:''});invoiceSelected=person;feedback=wz('התשלום נרשם. עכשיו מפיקים את הקבלה ב-Slate ומדביקים כאן את הקישור.','Платёж записан. Оформите квитанцию в Slate и вставьте ссылку здесь.');saveDemo();render()}
function saveSlateReceipt(e,id){e.preventDefault();const r=receipts.find(x=>x.id===id);if(!r)return;const f=new FormData(e.target),no=String(f.get('slateNo')||'').trim(),url=String(f.get('slateUrl')||'').trim();let ok=false;try{ok=new URL(url).protocol==='https:'}catch(_){}if(!no||!ok){alert(wz('יש להזין מספר קבלה וקישור שמתחיל ב-https://','Укажите номер квитанции и ссылку, начинающуюся с https://'));return}r.slateNo=no;r.slateUrl=url;r.status='issued';feedback=wz('הקבלה נשמרה. אפשר לשלוח ללקוח ב-WhatsApp.','Квитанция сохранена. Можно отправить в WhatsApp.');saveDemo();render()}
function sendReceiptWhatsApp(id){const r=receipts.find(x=>x.id===id);if(!r||!r.slateUrl)return;const p=people[r.person]||{},phone=waPhone(p.phone);if(!phone){alert(wz('אין מספר טלפון תקין למתאמן.','У клиента нет корректного номера телефона.'));return}const msg=`שלום ${p.name||''},\nמצורפת הקבלה מס׳ ${r.slateNo} על סך ₪${r.amount.toFixed(2)} עבור ${r.description}:\n${r.slateUrl}\nתודה, סטודיו לאוניד`;window.open('https://wa.me/'+phone+'?text='+encodeURIComponent(msg),'_blank','noopener');r.status='sent';r.sentAt=todayISO();saveDemo();render()}
function editSlateReceipt(id){const r=receipts.find(x=>x.id===id);if(!r)return;r.status='toIssue';saveDemo();render()}
function deletePayment(id){const r=receipts.find(x=>x.id===id);if(!r||r.status!=='toIssue')return;if(!confirm(wz('למחוק את רישום התשלום? (הפעולה לא מוחקת דבר ב-Slate)','Удалить запись о платеже? (В Slate ничего не удаляется)')))return;receipts=receipts.filter(x=>x.id!==id);saveDemo();render()}
function invoices(){const he=lang==='he';const row=(r)=>{const p=people[r.person];const name=p?esc(pn(p)):'—';const who=p?`<button class="member-shortcut" onclick="choose(${r.person})">${name}</button>`:name;let receipt='—',act='';if(r.status==='toIssue'){receipt=`<form class="receipt-link-form" onsubmit="saveSlateReceipt(event,'${r.id}')"><input name="slateNo" placeholder="${wz('מס׳ קבלה','№ квитанции')}" aria-label="${wz('מספר הקבלה ב-Slate','Номер квитанции в Slate')}" required><input name="slateUrl" type="url" placeholder="https://..." aria-label="${wz('קישור לקבלה ב-Slate','Ссылка на квитанцию в Slate')}" required><button class="btn" type="submit">${wz('שמירה','Сохранить')}</button></form>`;act=`<a class="btn alt" href="${SLATE_APP}" target="_blank" rel="noopener">${wz('פתיחת Slate','Открыть Slate')}</a> <button class="link" onclick="deletePayment('${r.id}')">${wz('מחיקה','Удалить')}</button>`}else{receipt=`<bdi>${esc(r.slateNo)}</bdi> · <a href="${esc(r.slateUrl)}" target="_blank" rel="noopener">${wz('צפייה בקבלה','Открыть')}</a>`;act=`<button class="btn whatsapp-btn" onclick="sendReceiptWhatsApp('${r.id}')">${r.status==='sent'?wz('שליחה שוב ב-WhatsApp','Отправить снова'):wz('שליחה ב-WhatsApp','Отправить в WhatsApp')}</button> <button class="link" onclick="editSlateReceipt('${r.id}')">${wz('תיקון','Исправить')}</button>`}return `<tr><td data-label="${t('date')}">${fmt(r.date)}</td><td>${who}</td><td data-label="${t('amount')}">₪${r.amount.toFixed(2)}</td><td data-label="${t('status')}">${receiptStatus(r.status)}</td><td data-label="${wz('קבלה','Квитанция')}">${receipt}</td><td>${act}</td></tr>`};return `${receiptsAlert()}<div class="panel"><h2>${he?'רישום תשלום':'Записать платёж'}</h2><p class="muted">${he?'הקבלה החוקית מופקת ב-Slate (תוכנה רשומה ברשות המסים). האתר רק רושם את התשלום, שומר את הקישור לקבלה ושולח אותה למתאמן — הוא לא מפיק מסמכים חשבונאיים.':'Официальная квитанция оформляется в Slate (программа, зарегистрированная в налоговой). Сайт только записывает платёж, хранит ссылку на квитанцию и отправляет её клиенту — он не создаёт бухгалтерских документов.'}</p><form onsubmit="recordPayment(event)" class="grid-form"><label class="field">${t('name')}<select name="person">${options(invoiceSelected)}</select></label><label class="field">${t('amount')}<input type="number" name="amount" min="1" step="0.01" value="150" required></label><label class="field">${he?'אמצעי תשלום':'Способ оплаты'}<select name="method"><option value="מזומן">${he?'מזומן':'Наличные'}</option><option value="העברה בנקאית">${he?'העברה בנקאית':'Банковский перевод'}</option><option value="ביט">${he?'ביט':'Bit'}</option><option value="כרטיס">${he?'כרטיס':'Карта'}</option></select></label><label class="field">${t('date')}<input type="date" name="date" value="${todayISO()}" required></label><label class="field">${he?'תיאור':'Описание'}<input name="description" value="${he?'מנוי חודשי':'Месячный абонемент'}"></label><button class="btn" type="submit">${he?'רישום תשלום':'Записать платёж'}</button></form></div><div class="panel"><h2>${he?'תשלומים וקבלות':'Платежи и квитанции'}</h2><ol class="slate-steps small muted"><li>${he?'רושמים את התשלום כאן.':'Запишите платёж здесь.'}</li><li>${he?'מפיקים קבלה ב-Slate (מהטלפון) ומעתיקים את מספר הקבלה ואת קישור האימות שלה.':'Оформите квитанцию в Slate и скопируйте её номер и ссылку.'}</li><li>${he?'מדביקים כאן ושולחים ב-WhatsApp בלחיצה.':'Вставьте здесь и отправьте в WhatsApp одним нажатием.'}</li></ol><div class="table responsive-table-target receipt-ledger-scroll" tabindex="0" role="region" aria-label="${he?'תשלומים וקבלות':'Платежи и квитанции'}"><table><thead><tr><th>${t('date')}</th><th>${t('name')}</th><th>${t('amount')}</th><th>${t('status')}</th><th>${he?'קבלה ב-Slate':'Квитанция Slate'}</th><th>${t('actions')}</th></tr></thead><tbody>${receipts.map(row).join('')||`<tr><td colspan="6">${he?'טרם נרשמו תשלומים':'Платежей пока нет'}</td></tr>`}</tbody></table></div></div>`}

const healthQuestions=[["האם הרופא שלך אמר לך שאתה סובל ממחלת לב?","Говорил ли вам врач, что у вас заболевание сердца?"],["האם אתה חש כאבים בחזה בזמן מנוחה?","Бывает ли боль в груди в покое?"],["האם אתה חש כאבים בחזה במהלך פעילויות שגרה ביום־יום?","Бывает ли боль в груди во время повседневных дел?"],["האם אתה חש כאבים בחזה בזמן פעילות גופנית?","Бывает ли боль в груди при физической активности?"],["האם במהלך השנה החולפת איבדת שיווי משקל עקב סחרחורת (שלא נבעה מנשימת יתר)?","Теряли ли вы равновесие из-за головокружения за последний год (не связанного с гипервентиляцией)?"],["האם במהלך השנה החולפת איבדת את הכרתך?","Теряли ли вы сознание за последний год?"],["אם רופא אבחן אצלך אסתמה: האם בשלושת החודשים האחרונים נזקקת לטיפול תרופתי?","Если врач диагностировал астму: требовалось ли лечение лекарствами за последние три месяца?"],["אם רופא אבחן אצלך אסתמה: האם בשלושת החודשים האחרונים סבלת מקוצר נשימה או מצפצופים?","Если врач диагностировал астму: были ли одышка или свистящее дыхание за последние три месяца?"],["האם בן משפחה מדרגת קרבה ראשונה נפטר ממחלת לב?","Умирал ли близкий родственник первой степени родства от болезни сердца?"],["האם בן משפחה מדרגת קרבה ראשונה נפטר ממוות פתאומי בגיל מוקדם (גבר לפני גיל 55, אישה לפני גיל 65)?","Был ли случай внезапной смерти близкого родственника в раннем возрасте (мужчина до 55, женщина до 65 лет)?"],["האם הרופא שלך אמר לך בחמש השנים האחרונות לבצע פעילות גופנית רק תחת השגחה רפואית?","Советовал ли врач за последние пять лет заниматься физической активностью только под медицинским наблюдением?"],["האם אתה סובל ממחלה כרונית אחרת שעשויה למנוע או להגביל פעילות גופנית?","Есть ли другое хроническое заболевание, которое может ограничивать физическую активность?"],["לנשים בהריון: האם ההיריון הנוכחי או היריון קודם הוגדר בסיכון?","Для беременных: относилась ли текущая или предыдущая беременность к группе риска?"]];
let healthData={};
const embeddedHealthPdf='assets/health-declaration.pdf';
let signCanvas=null,signCtx=null,signActive=false,signTouched=false,signData='';
function initSignature(){const c=document.getElementById('health-sign');if(!c)return;signCanvas=c;const dpr=Math.max(1,window.devicePixelRatio||1);const w=c.getBoundingClientRect().width;c.width=Math.round(w*dpr);c.height=Math.round(210*dpr);signCtx=c.getContext('2d');signCtx.setTransform(dpr,0,0,dpr,0,0);signCtx.strokeStyle='#173e32';signCtx.lineWidth=2.6;signCtx.lineCap='round';signCtx.lineJoin='round';if(signData){const img=new Image();img.onload=()=>signCtx.drawImage(img,0,0,w,210);img.src=signData;signTouched=true}else{signTouched=false}const pos=e=>{const r=c.getBoundingClientRect();return {x:(e.clientX-r.left),y:(e.clientY-r.top)*210/r.height}};c.onpointerdown=e=>{e.preventDefault();c.setPointerCapture(e.pointerId);signActive=true;const q=pos(e);signCtx.beginPath();signCtx.moveTo(q.x,q.y);signCtx.lineTo(q.x+.2,q.y+.2);signCtx.stroke();signTouched=true};c.onpointermove=e=>{if(!signActive)return;e.preventDefault();const q=pos(e);signCtx.lineTo(q.x,q.y);signCtx.stroke()};c.onpointerup=c.onpointercancel=()=>{signActive=false;if(signTouched)signData=c.toDataURL('image/png')};}
function clearSignature(){if(signCanvas&&signCtx){signCtx.clearRect(0,0,signCanvas.width,signCanvas.height);signTouched=false;signData=''}}
function healthAge(){const v=document.querySelector('input[name=birth]')?.value;const out=document.getElementById('health-age');if(!out)return;let age='—';if(v){const b=new Date(v+'T00:00:00'),n=new Date();let a=n.getFullYear()-b.getFullYear();if(n.getMonth()<b.getMonth()||(n.getMonth()===b.getMonth()&&n.getDate()<b.getDate()))a--;if(a>=0&&a<120)age=String(a)}out.textContent=(lang==='he'?'גיל: ':'Возраст: ')+age;document.getElementById('minor-block').hidden=!(age!=='—'&&Number(age)<18)}
function health(){const he=lang==='he',p=people[healthSelected],name=esc(pn(p));return `<div class="steps"><span class="step">1 · ${t('newMember')}</span><span class="step">2 · ${t('health')}</span><span class="step">3 · PDF</span></div><div class="panel health-form"><div class="health-head"><span class="health-symbol">101</span><div><h2>טופס 101 הצהרת בריאות</h2><p>${he?'הצהרת בריאות למבקש להתאמן בחדר כושר':'Декларация здоровья для занятий в тренажёрном зале'}</p></div></div><div class="warning">${he?'אב טיפוס מקומי בלבד: יש לבדוק שהנוסח תואם לדרישות העדכניות לפני שימוש אמיתי. המידע אינו נשמר בשרת ואינו נשלח.':'Локальный макет: перед реальным применением нужно проверить актуальность требований. Данные не передаются и не сохраняются на сервере.'}</div><label class="field">${he?'בחירת מתאמן':'Выберите клиента'}<select onchange="healthSelected=+this.value;healthVisible=false;render()">${options(healthSelected)}</select></label><h3>${he?'איך תרצו למלא את הטופס?':'Как заполнить форму?'}</h3><div class="health-choice"><button type="button" class="${healthMode==='web'?'chosen':''}" onclick="setHealthMode('web')">✍ ${he?'מילוי באתר':'Заполнить на сайте'}</button><button type="button" class="${healthMode==='pdf'?'chosen':''}" onclick="setHealthMode('pdf')">▤ ${he?'מילוי באמצעות PDF':'Заполнить PDF'}</button></div>${healthMode==='pdf'?`<div class="pdf-mode"><h3>${he?'טופס מקורי להורדה':'Оригинальный бланк PDF'}</h3><p class="hint">${he?'הורידו את הטופס המצורף, מלאו וחתמו עליו ולאחר מכן בחרו את הקובץ המלא.':'Скачайте вложенный бланк, заполните и подпишите его, затем выберите готовый файл.'}</p><a download="health-declaration-reference.pdf" href="${embeddedHealthPdf}">⬇ ${he?'הורדת PDF':'Скачать PDF'}</a><form onsubmit="pdfDemo(event)"><label class="field">${he?'בחירת קובץ PDF מלא וחתום':'Выберите заполненный PDF'}<input type="file" accept="application/pdf,.pdf" required></label><button class="btn">${he?'בדיקת הקובץ (הדגמה)':'Проверить файл (демо)'}</button></form><p class="hint" id="pdf-demo-result" role="status"></p></div>`:''}${healthMode==='web'?`<form id="medical-web-form" onsubmit="makeHealth(event)"><h3 class="section-h">${he?'פרטי המתאמן':'Данные клиента'}</h3><div class="health-meta">${field(he?'שם מלא':'Полное имя','name','text',name)}${field(he?'תעודת זהות':'Удостоверение личности','identity','text','')}${field(he?'תאריך לידה':'Дата рождения','birth','date','')}${field(he?'טלפון':'Телефон','phone','tel',p.phone||'')}${field(he?'דוא״ל':'Электронная почта','email','email',p.email||'')}${field(he?'תאריך מילוי':'Дата заполнения','date','date',new Date().toISOString().slice(0,10))}</div><div id="health-age" class="health-age"></div><div id="minor-block" class="health-file" hidden><h3>${he?'אישור הורה למתאמן מתחת לגיל 18':'Согласие родителя для несовершеннолетнего'}</h3><label class="field">${he?'שם ההורה':'Имя родителя'}<input name="parentName" autocomplete="off"></label><label class="field">${he?'סוגי אימונים שההורה מאשר':'Разрешённые виды тренировок'}<input name="parentTraining" autocomplete="off"></label><label class="check"><input type="checkbox" name="parentConsent">${he?'אני מאשר/ת כהורה את השתתפות הקטין באימונים המצוינים':'Я как родитель разрешаю указанные тренировки'}</label><p class="muted small">${he?'בגרסה האמיתית נדרשת גם חתימת ההורה.':'В рабочей версии потребуется также подпись родителя.'}</p></div><h3 class="section-h">${he?'חלק א׳ — שאלון רפואי':'Часть A — Медицинская анкета'}</h3><p class="muted">${he?'יש לענות על כל סעיף בכנות. השאלות מבוססות על המסמך שצירפת, לרבות תתי־השאלות.':'Ответьте на каждый пункт. Вопросы основаны на приложенном документе, включая подпункты.'}</p>${healthQuestions.map((q,i)=>`<fieldset class="medical-question"><legend>${i+1}. ${he?q[0]:q[1]} <span style="color:#a94d49">*</span></legend><div class="radio-row"><label><input type="radio" name="q${i}" value="yes" required> ${he?'כן':'Да'}</label><label><input type="radio" name="q${i}" value="no" required> ${he?'לא':'Нет'}</label></div></fieldset>`).join('')}<h3 class="section-h">${he?'חלק ב׳ — הנחיות':'Часть B — Указания'}</h3><div class="notice">${he?'אם ענית ״כן״ על אחד הסעיפים, יש להמציא אישור רפואי לפני אישור האימון. לפי מסמך הייחוס, האישור הרפואי צריך להיות בן פחות משלושה חודשים. במקרה של שינוי במצב הרפואי יש להתייעץ עם רופא.':'Если хотя бы один ответ «Да», перед допуском к занятиям необходимо медицинское заключение. В документе-образце указано, что заключение должно быть выдано не более трёх месяцев назад. При изменении состояния здоровья проконсультируйтесь с врачом.'}</div><label class="field health-file">${he?'צירוף אישור רפואי (אם נדרש)':'Приложить медицинское заключение (при необходимости)'}<input type="file" name="certificate" accept="application/pdf,image/png,image/jpeg"></label><h3 class="section-h">${he?'חלק ג׳ — הצהרה וחתימה':'Часть C — Декларация и подпись'}</h3><p>${he?'אני מצהיר/ה שקראתי והבנתי את השאלון, מילאתי אותו בעצמי ומסרתי מידע מלא ונכון לגבי מצבי הרפואי. ידוע לי כי לפי מסמך הייחוס יש לחדש הצהרת בריאות לאחר שנתיים.':'Я подтверждаю, что прочитал(а) и понял(а) анкету, заполнил(а) её лично и предоставил(а) полную и достоверную информацию о здоровье. В исходном документе указано обновление декларации через два года.'}</p><label class="field">${he?'הערות נוספות (רשות)':'Дополнительные замечания (необязательно)'}<textarea name="notes"></textarea></label><label class="check"><input type="checkbox" name="truth" required>${he?'אני מאשר/ת שהפרטים נכונים ושקראתי את ההנחיות':'Подтверждаю достоверность ответов и ознакомление с указаниями'}</label><label class="check"><input type="checkbox" name="privacy" required>${he?'אני מסכים/ה לשימוש במידע לצורך טיפול בהצהרה במסגרת הסטודיו (הדגמה בלבד)':'Согласен(на) на обработку данных для оформления декларации в студии (демо)'}</label><h3>${he?'חתימת המתאמן — חתמו באצבע או בעכבר':'Подпись клиента — пальцем или мышью'}</h3><canvas id="health-sign" class="signature-pad" aria-label="${he?'אזור חתימה':'Поле подписи'}"></canvas><div class="sign-help"><span class="muted small">${he?'יש לחתום בתוך המסגרת':'Подпишите внутри рамки'}</span><button type="button" class="btn secondary" onclick="clearSignature()">${he?'נקה חתימה':'Очистить подпись'}</button></div><button class="btn" type="submit">${he?'בדיקה ותצוגה מקדימה':'Проверить и показать документ'}</button></form>`:''}</div>${healthVisible&&healthMode==='web'?healthPreview():''}`}
function makeHealth(e){e.preventDefault();if(!signTouched){alert(lang==='he'?'יש לחתום בתוך אזור החתימה':'Необходимо поставить подпись');return}const f=new FormData(e.target);const birth=f.get('birth');if(!birth){alert(lang==='he'?'יש למלא תאריך לידה':'Укажите дату рождения');return}const age=Number(document.getElementById('health-age').textContent.replace(/\D/g,''));if(age<18&&(!f.get('parentName')||!f.get('parentConsent'))){alert(lang==='he'?'יש למלא אישור הורה':'Необходимо согласие родителя');return}healthData={};for(const [k,v] of f.entries())if(!(v instanceof File))healthData[k]=v;healthData.hasYes=healthQuestions.some((q,i)=>healthData['q'+i]==='yes');const file=f.get('certificate');healthData.certificate=file&&file.size?file.name:'';healthData.sign=signCanvas.toDataURL('image/png');healthData.minor=age<18;if(wizardHealthActive){wizard.healthResult=healthData.hasYes?'positive':'negative';wizard.healthSigned=true;wizard.healthMethod='web';wizard.certificate=!!healthData.certificate;wizard.certApproved=false;wizardHealthActive=false;wizardStep=1;page='newMember';}healthVisible=true;feedback=lang==='he'?'תצוגת מסמך נוצרה. לא בוצעה שליחה או שמירה בשרת.':'Предпросмотр готов. Данные не отправлены и не сохранены на сервере.';render()}
function healthPreview(){const he=lang==='he',d=healthData;return `<div class="panel">${wizard.healthSigned&&wizardStep===1?`<button class="btn" onclick="go('newMember')">${he?'חזרה להמשך ההרשמה':'Вернуться к регистрации'}</button>`:''}<h2>${he?'תצוגה מקדימה — הצהרת בריאות':'Предпросмотр — декларация здоровья'}</h2>${d.hasYes?`<div class="warning">${he?'נמצאה תשובה חיובית: יש לבדוק אישור רפואי לפני אישור האימון.':'Есть ответ «Да»: требуется проверить медицинское заключение перед допуском.'}</div>`:''}<div class="preview health-print" id="health-print" dir="${he?'rtl':'ltr'}"><h2>טופס 101 הצהרת בריאות</h2><p class="print-muted">${he?'מסמך הדגמה — אינו אישור רפואי':'Демонстрационный документ — не медицинское разрешение'}</p><p><b>${he?'שם מלא':'Имя'}:</b> ${esc(d.name||'')} &nbsp; <b>${he?'תאריך':'Дата'}:</b> ${esc(d.date||'')}</p><p><b>${he?'תעודת זהות':'ID'}:</b> ${esc(d.identity||'')} &nbsp; <b>${he?'תאריך לידה':'Дата рождения'}:</b> ${esc(d.birth||'')}</p><p><b>${he?'טלפון':'Телефон'}:</b> ${esc(d.phone||'')} &nbsp; <b>${he?'דוא״ל':'E-mail'}:</b> ${esc(d.email||'')}</p><h3>${he?'חלק א׳ — שאלון רפואי':'Часть A — Анкета'}</h3>${healthQuestions.map((q,i)=>`<div class="print-qa"><b>${i+1}. ${he?q[0]:q[1]}</b> — ${d['q'+i]==='yes'?(he?'כן':'Да'):(he?'לא':'Нет')}</div>`).join('')}<h3>${he?'חלק ב׳ — הנחיות':'Часть B — Указания'}</h3><p>${he?'תשובה חיובית מחייבת בדיקה ואישור רפואי מתאים לפני אימון, בהתאם להוראות החלות.':'Положительный ответ требует соответствующей медицинской проверки перед занятиями.'}</p><p><b>${he?'אישור רפואי מצורף':'Медицинское заключение'}:</b> ${esc(d.certificate|| (he?'לא צורף':'Не приложено'))} <span class="print-muted">(${he?'שם הקובץ בלבד; הקובץ לא נכלל בהדפסה':'только имя файла; файл не включён в печать'})</span></p><h3>${he?'חלק ג׳ — הצהרה':'Часть C — Декларация'}</h3><p>${he?'הנני מצהיר/ה שמסרתי מידע נכון ומלא ושקראתי את ההנחיות.':'Подтверждаю достоверность сведений и ознакомление с указаниями.'}</p>${d.notes?`<p><b>${he?'הערות':'Примечания'}:</b> ${esc(d.notes)}</p>`:''}${d.minor?`<p><b>${he?'שם הורה':'Родитель'}:</b> ${esc(d.parentName||'')} — ${esc(d.parentTraining||'')}</p>`:''}<p><b>${he?'חתימה':'Подпись'}:</b></p><img class="print-sign" alt="Signature" src="${d.sign}"><p class="print-muted">${he?'חתימה מצוירת בדפדפן — אין אימות זהות או חתימה מוסמכת.':'Нарисованная подпись — без проверки личности и сертифицированной электронной подписи.'}</p></div><div class="row" style="margin-top:15px"><button class="btn" onclick="printBlock('health-print')">${he?'הדפסה / שמירה כ־PDF':'Печать / сохранить PDF'}</button></div><p class="muted small">${he?'אין שליחת דוא״ל, שמירה מאובטחת או אימות חתימה בגרסת הדגמה.':'В демо нет отправки писем, защищённого хранения и проверки подписи.'}</p></div>`}
function reminders(){let s=loadSettings();return `<div class="panel" style="max-width:760px"><h2>${t('reminderTitle')}</h2><div class="notice">${t('demo')} · WhatsApp + E-mail · 2 ${lang==='he'?'ימים':'дня'}</div><form onsubmit="saveSettings(event)"><label class="check"><input name="enabled" type="checkbox" ${s.enabled?'checked':''}>${t('enabled')}</label><h3>${t('before')}</h3><label class="check"><input type="radio" name="days" value="1" ${s.days==='1'?'checked':''}>${t('one')}</label><label class="check"><input type="radio" name="days" value="2" ${s.days==='2'?'checked':''}>${t('two')}</label><h3>${t('channels')}</h3><label class="check"><input type="checkbox" name="wa" ${s.wa?'checked':''}>WhatsApp</label><label class="check"><input type="checkbox" name="mail" ${s.mail?'checked':''}>E-mail</label><button class="btn">${t('save')}</button></form><p class="muted small">${t('footer')}</p></div><div class="panel"><div class="dashboard-title"><h2>${lang==='he'?'מתאמנים ותאריכי חידוש':'Клиенты и даты продления'}</h2></div>${membersTable()}</div>`}
function loadSettings(){try{return JSON.parse(localStorage.getItem('leonid-demo-settings'))||{enabled:true,days:'2',wa:true,mail:true}}catch{return {enabled:true,days:'2',wa:true,mail:true}}}function saveSettings(e){e.preventDefault();const f=new FormData(e.target),s={enabled:f.has('enabled'),days:f.get('days'),wa:f.has('wa'),mail:f.has('mail')};try{localStorage.setItem('leonid-demo-settings',JSON.stringify(s))}catch{}feedback=t('saved');render()}
function client(){const p=people[selected];return `<div class="notice">${t('clientIntro')} · ${t('noLogin')}</div><div class="panel"><label class="field">${t('chooseMember')}<select onchange="selected=+this.value;render()">${options(selected)}</select></label><h2>${t('myDetails')}</h2><p><b>${esc(pn(p))}</b> · ${p.age}</p><p><bdi>${p.phone}</bdi> · <bdi>${p.email}</bdi></p><h2>${t('mySubscription')}</h2><p>${stat(p.status)} · ${t('end')}: ${fmt(p.end)}</p><h2>${t('myDocuments')}</h2><p>${t('healthStatus')}: ${stat(p.medical?'received':'missing')}</p><div class="row">${btn(t('openHealth'),`healthFor(${selected})`,'')}${btn(t('profile'),"go('profile')")}</div></div>`}
function printBlock(id){const el=document.getElementById(id);if(!el)return;const w=window.open('','_blank');if(!w){alert('Pop-up blocked');return}w.document.write('<!doctype html><html lang="'+lang+'" dir="'+(lang==='he'?'rtl':'ltr')+'"><meta charset="utf-8"><title>DEMO</title><style>body{font:16px Arial;padding:35px;line-height:1.7}.badge{color:#a65b00}</style>'+el.innerHTML+'</html>');w.document.close();w.focus();w.print()}

// Guided registration: local-only demonstration; no medical data is sent or retained.
let wizardHealthActive=false,wizardTempIndex=-1;let wizardStep=0,wizard={name:'',phone:'',email:'',birth:'',healthMethod:'web',healthResult:'none',healthSigned:false,certApproved:false,certificate:false,amount:250,payment:'cash',paid:false,period:1,receipt:null};
const wz=(he,ru)=>lang==='he'?he:ru;
function wizardProgress(){let labels=lang==='he'?['פרטים','בריאות','תשלום','קבלה','סיום']:['Данные','Здоровье','Оплата','Квитанция','Готово'];return `<div class="wizard-progress">${labels.map((x,i)=>`<div class="${i===wizardStep?'current':i<wizardStep?'done':''}">${i+1}. ${x}</div>`).join('')}</div>`}
function wizardNav(){return `<div class="wizard-actions">${wizardStep>0?`<button class="btn alt" type="button" onclick="wizardStep--;render()">${wz('← חזרה','← Назад')}</button>`:'<span></span>'}${wizardStep<4?`<button class="btn" type="button" onclick="wizardNext()">${wz('המשך ←','Далее →')}</button>`:`<button class="btn" type="button" onclick="wizardReset()">${wz('רישום נוסף','Новая регистрация')}</button>`}</div>`}
function wizardOpenHealth(){
 if(!wizard.name||!wizard.birth){alert(wz('יש להשלים תחילה את פרטי המתאמן','Сначала заполните данные клиента'));return}
 if(wizardTempIndex<0){wizardTempIndex=people.length;people.push({name:wizard.name,ru:wizard.name,username:'demo-draft',age:0,phone:wizard.phone,email:wizard.email,start:'',end:'',status:'pending',medical:false,measure:[['2026-11-03',170,70,20,30,50]],temporary:true})}
 healthSelected=wizardTempIndex;wizardHealthActive=true;healthVisible=false;signData='';signTouched=false;healthMode='web';go('health');
}
function wizardNext(){
 if(wizardStep===0){const form=document.getElementById('wizard-person');if(!form.reportValidity())return;const f=new FormData(form);for(const k of ['name','phone','email','birth'])wizard[k]=String(f.get(k)||'')}
 if(wizardStep===1){if(!wizard.healthSigned){alert(wz('יש למלא ולחתום על הצהרת הבריאות לפני המשך','Заполните и подпишите декларацию перед продолжением'));return}if(wizard.healthResult==='positive'&&!wizard.certApproved){/* payment may proceed; training blocked */}}
 if(wizardStep===2){const form=document.getElementById('wizard-payment');if(!form.reportValidity())return;const f=new FormData(form);wizard.amount=Number(f.get('amount'));wizard.payment=f.get('method');wizard.paid=f.get('paid')==='yes';wizard.period=Number(f.get('period'));if(wizard.paid&&!(wizard.amount>0))return}
 if(wizardStep===3){if(wizard.paid&&!wizard.receipt){wizard.receipt=newPayId();receipts.unshift({id:wizard.receipt,person:people.length,amount:Number(wizard.amount)||0,method:String(wizard.payment||''),date:todayISO(),description:'מנוי חדש',status:'toIssue',slateNo:'',slateUrl:''})}if(!wizard.saved){let d=new Date();let end=new Date(d);end.setMonth(end.getMonth()+wizard.period);let age=new Date().getFullYear()-Number(wizard.birth.slice(0,4));const p={name:wizard.name,ru:wizard.name,username:'demo.'+Date.now(),age,phone:wizard.phone,email:wizard.email,start:d.toISOString().slice(0,10),end:end.toISOString().slice(0,10),status:wizard.paid?'active':'pending',medical:false,medicalReview:wizard.healthResult==='negative'?'signed-demo':'pending',measure:[],demoAdded:true};people.push(p);wizard.saved=true;wizard.memberIndex=people.length-1;if(wizardTempIndex>=0){people.splice(wizardTempIndex,1);wizardTempIndex=-1;wizard.memberIndex--;for(const r of receipts)if(r.id===wizard.receipt)r.person=wizard.memberIndex}saveDemo();} }
 wizardStep=Math.min(4,wizardStep+1);render()
}
function wizardReset(){if(wizardTempIndex>=0){people.splice(wizardTempIndex,1);wizardTempIndex=-1}wizardStep=0;wizard={name:'',phone:'',email:'',birth:'',healthMethod:'web',healthResult:'none',healthSigned:false,certApproved:false,certificate:false,amount:250,payment:'cash',paid:false,period:1,receipt:null};render()}
function wizardHealthStatus(){if(wizard.healthResult==='negative')return ['ok',wz('הצהרה הושלמה — ללא תשובות חיוביות','Декларация заполнена — без положительных ответов')];if(wizard.healthResult==='positive')return ['warn',wizard.certApproved?wz('אישור רפואי נבדק ידנית (הדגמה)','Справка проверена вручную (демо)'):wz('נדרש אישור רפואי — אין אישור להתאמן','Нужна медицинская справка — занятия не разрешены')];return ['warn',wz('הצהרת בריאות טרם הושלמה — אין אישור להתאמן','Декларация не завершена — занятия не разрешены')]}
function newMember(){const hs=wizardHealthStatus();let body='';if(wizardStep===0)body=`<form id="wizard-person" onsubmit="event.preventDefault();wizardNext()"><div class="grid2">${field(wz('שם מלא','Имя и фамилия'),'name','text',wizard.name)}${field(wz('טלפון','Телефон'),'phone','tel',wizard.phone)}${field(wz('דוא״ל','Эл. почта'),'email','email',wizard.email)}${field(wz('תאריך לידה','Дата рождения'),'birth','date',wizard.birth)}</div></form>`;
if(wizardStep===1)body=`<div class="panel"><h3>${wz('הצהרת בריאות חתומה','Подписанная декларация здоровья')}</h3><p>${wz('מלאו את השאלון המלא וחתמו. אין אפשרות לסמן השלמה ידנית.','Заполните полную анкету и подпишите. Ручная отметка недоступна.')}</p><button class="btn" type="button" onclick="wizardOpenHealth()">${wz('מילוי הצהרה באתר','Заполнить декларацию онлайн')}</button><div class="${wizard.healthSigned?'wizard-ok':'wizard-warning'}">${wizard.healthSigned?wz('הצהרה נחתמה ונקלטה בסשן ההדגמה','Декларация подписана в демо-сеансе'):wz('נדרשת הצהרה חתומה','Требуется подписанная декларация')}</div>${wizard.healthResult==='positive'?`<div class="wizard-warning">${wz('נמצאה תשובה חיובית: אין אישור להתאמן. אישור רפואי מחייב בדיקה ידנית.','Есть ответ Да: тренировки запрещены до ручной проверки медицинского заключения.')}</div><label class="check"><input type="checkbox" onchange="wizard.certApproved=this.checked" ${wizard.certApproved?'checked':''}>${wz('מנהל בדק ידנית את האישור הרפואי (הדגמה בלבד)','Администратор вручную проверил справку (только демо)')}</label>`:''}<p class="muted small">${wz('העלאת PDF חתום דורשת אימות נפרד; לא ניתן לסמן PDF כמאושר אוטומטית.','Загруженный подписанный PDF требует отдельной проверки.')}</p></div>`;
if(wizardStep===2)body=`<form id="wizard-payment" onsubmit="event.preventDefault();wizardNext()"><div class="grid2"><label class="field">${wz('משך מנוי','Срок абонемента')}<select name="period"><option value="1">${wz('חודש אחד','1 месяц')}</option><option value="2">${wz('חודשיים','2 месяца')}</option></select></label>${field(wz('סכום ₪','Сумма ₪'),'amount','number',wizard.amount)}<label class="field">${wz('אמצעי תשלום','Способ оплаты')}<select name="method"><option value="cash">${wz('מזומן','Наличные')}</option><option value="transfer">${wz('העברה בנקאית','Перевод')}</option><option value="card">${wz('כרטיס','Карта')}</option></select></label><label class="field">${wz('האם התקבל תשלום?','Оплата получена?')}<select name="paid"><option value="no">${wz('לא — ממתין','Нет — ожидается')}</option><option value="yes" ${wizard.paid?'selected':''}>${wz('כן — שולם','Да — оплачено')}</option></select></label></div></form><div class="${hs[0]==='ok'?'wizard-ok':'wizard-warning'}">${hs[1]}</div>`;
if(wizardStep===3)body=`<div class="wizard-summary"><div><b>${wz('מתאמן','Клиент')}</b><p>${esc(wizard.name)}</p></div><div><b>${wz('תשלום','Оплата')}</b><p>${wizard.amount} ₪ · ${wizard.paid?wz('שולם','Оплачено'):wz('ממתין','Ожидается')}</p></div></div>${wizard.paid?`<div class="wizard-ok">${wz('התשלום סומן כשולם. בשלב הבא יוקצה מספר קבלה לדוגמה בלבד.','Оплата отмечена. На следующем шаге будет присвоен демонстрационный номер квитанции.')}</div>`:`<div class="wizard-warning">${wz('לא התקבל תשלום — לא תופק קבלה.','Оплата не получена — квитанция не создаётся.')}</div>`}<p class="muted small">${wz('המספר DEMO אינו מספר קבלה חוקית. אין שליחת דוא״ל או סליקה.','Номер DEMO не является действительной квитанцией. Письма и платежи не отправляются.')}</p>`;
if(wizardStep===4)body=`<div class="wizard-ok"><h3>${wz('טיוטת רישום הושלמה','Черновик регистрации завершён')}</h3><p>${esc(wizard.name)}</p></div><div class="wizard-summary"><div><b>${wz('מצב רפואי','Медицинский статус')}</b><p>${hs[1]}</p></div><div><b>${wz('קבלה','Квитанция')}</b><p>${wizard.receipt?wz('תשלום נרשם · קבלה להפקה ב-Slate','Платёж записан · квитанция в Slate'):wz('לא הופקה — אין תשלום','Не создана — нет оплаты')}</p></div><div><b>${wz('תזכורת חידוש','Напоминание')}</b><p>${wz('יומיים לפני · WhatsApp + דוא״ל (הדגמה)','За 2 дня · WhatsApp + e-mail (демо)')}</p></div><div><b>${wz('שמירה','Сохранение')}</b><p>${wz('נשמר בדפדפן בלבד — ללא נתונים רפואיים','Сохранено только в браузере, без медданных')}</p></div></div><div class="wizard-warning">${wz('אין אישור כניסה לאימון עד להשלמת ובדיקת מסמכי הבריאות. המידע אינו נשמר במערכת אמיתית.','Допуск к занятиям невозможен до завершения и проверки медицинских документов. Данные не сохраняются в реальной системе.')}</div>`;
return `<div class="panel"><div class="row between"><h2>${wz('רישום מתאמן — מסלול אחד','Регистрация клиента — единый процесс')}</h2><span class="badge">${wz('הדגמה','Демо')}</span></div>${wizardProgress()}${body}${wizardNav()}</div>`}

function render(){document.documentElement.lang=lang;document.documentElement.dir=lang==='he'?'rtl':'ltr';const brandLabel=document.getElementById('brand');if(brandLabel)brandLabel.textContent=t('brand');document.querySelectorAll('[data-t]').forEach(el=>el.textContent=t(el.dataset.t));document.getElementById('language').value=lang;document.getElementById('role').value=role;document.querySelector('#role option[value=owner]').textContent=lang==='he'?'מנהל':'Администратор';document.querySelector('#role option[value=client]').textContent=lang==='he'?'מתאמן':'Клиент';const primary=document.getElementById('owner-new-action');primary.hidden=role!=='owner';primary.textContent=lang==='he'?'＋ מתאמן חדש':'＋ Новый клиент';let navKeys=role==='owner'?keys.slice(0,8):['client','health'];if(!navKeys.includes(page))page=navKeys[0];document.getElementById('nav').innerHTML=navKeys.map(k=>`<button class="${page===k?'active':''}" onclick="go('${k}')">${t(k)}</button>`).join('');document.getElementById('title').textContent=t(page);let html={dashboard,members,profile,newMember,monthlyBills,invoices,health,reminders,client}[page]();document.getElementById('pages').innerHTML=html+(feedback?`<div class="notice" role="status">${esc(feedback)}</div>`:'');feedback='';if(page==='health'&&healthMode==='web'){initSignature();const birth=document.querySelector('input[name=birth]');if(birth)birth.addEventListener('change',healthAge);healthAge()}}
document.getElementById('language').onchange=e=>{lang=e.target.value;render()};document.getElementById('role').onchange=e=>{role=e.target.value;page=role==='client'?'client':'dashboard';render()};
function closeTopMenus(){document.querySelectorAll('.custom-menu').forEach(menu=>menu.hidden=true);document.querySelectorAll('.custom-trigger').forEach(btn=>btn.setAttribute('aria-expanded','false'))}
function toggleTopMenu(which){const menu=document.getElementById(which+'-menu'),wasOpen=!menu.hidden;closeTopMenus();if(!wasOpen){menu.hidden=false;document.getElementById(which+'-trigger').setAttribute('aria-expanded','true')}}
function selectTopMenu(which,value){const select=document.getElementById(which);select.value=value;select.dispatchEvent(new Event('change',{bubbles:true}));closeTopMenus();document.getElementById(which+'-trigger').focus()}
function refreshTopMenuLabels(){document.getElementById('language-label').textContent=lang==='he'?'עברית':'Русский';document.getElementById('role-label').textContent=role==='owner'?(lang==='he'?'מנהל':'Администратор'):(lang==='he'?'מתאמן':'Клиент');document.querySelectorAll('.custom-control').forEach(group=>{const name=group.dataset.menu,current=name==='language'?lang:role;group.querySelectorAll('[data-value]').forEach(option=>option.setAttribute('aria-checked',String(option.dataset.value===current)))})}
document.addEventListener('click',e=>{if(!e.target.closest('.custom-control'))closeTopMenus()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeTopMenus()});
const originalRender=render;render=function(){originalRender();refreshTopMenuLabels()};render();
